    registerUnlockHandlers() {
        if (this.unlockHandlersRegistered || typeof window === 'undefined') return;
        this.unlockHandlersRegistered = true;
        const unlock = ()=>this.unlock();
        window.addEventListener('pointerdown', unlock);
        window.addEventListener('keydown', unlock);
        window.addEventListener('touchstart', unlock, {
            passive: true
        });
    }
    ensureAudioContext() {
        if (typeof window === 'undefined') return null;
        if (this.audioContext) return this.audioContext;
        const AudioContextConstructor = window.AudioContext ?? window.webkitAudioContext;
        if (!AudioContextConstructor) return null;
        this.audioContext = new AudioContextConstructor();
        this.masterGain = this.audioContext.createGain();
        this.musicGain = this.audioContext.createGain();
        this.sfxGain = this.audioContext.createGain();
        this.masterGain.gain.value = 1.0;
        this.updateBusGains();
        this.musicGain.connect(this.masterGain);
        this.sfxGain.connect(this.masterGain);
        this.masterGain.connect(this.audioContext.destination);
        this.noiseBuffer = this.getNoiseBuffer(this.audioContext);
        return this.audioContext;
    }
    getStageMusicDispatch(stageId) {
        switch(stageId){
            case 'startScreen':
                return {
                    play: ()=>this.playStartScreenMusic(),
                    loopMs: 1680
                };
            case 'lobby':
                return {
                    play: ()=>this.playLobbyMusic(),
                    loopMs: 48000
                };
            case 'networkMatrix':
                return {
                    play: ()=>this.playNetworkMatrixMusic(),
                    loopMs: 1450
                };
            case 'packetForge':
                return {
                    play: ()=>this.playPacketForgeMusic(),
                    loopMs: 1250
                };
            case 'cipherNull':
                return {
                    play: ()=>this.playCipherNullMusic(),
                    loopMs: 1550
                };
            case 'cipherNullDepth2':
                return {
                    play: ()=>this.playCipherNullDepth2Music(),
                    loopMs: 1300
                };
            case 'securityCore':
                return {
                    play: ()=>this.playSecurityCoreMusic(),
                    loopMs: 1300
                };
            case 'securityCoreDepth2':
                return {
                    play: ()=>this.playSecurityCoreDepth2Music(),
                    loopMs: 1100
                };
            case 'securityCoreDepth3':
                return {
                    play: ()=>this.playSecurityCoreDepth3Music(),
                    loopMs: 975
                };
            case 'kernelTerminus':
                return {
                    play: ()=>this.playKernelTerminusMusic(),
                    loopMs: 1200
                };
            case 'kernelTerminusDepth2':
                return {
                    play: ()=>this.playKernelTerminusDepth2Music(),
                    loopMs: 1025
                };
            case 'kernelTerminusDepth3':
                return {
                    play: ()=>this.playKernelTerminusDepth3Music(),
                    loopMs: 900
                };
            case 'gameTest':
                return {
                    play: ()=>this.playGameTestMusic(),
                    loopMs: 1040
                };
            default:
                {
                    console.warn(`[AudioManager] Unknown stageId "${stageId}", falling back to lobby music.`);
                    return {
                        play: ()=>this.playLobbyMusic(),
                        loopMs: 60000
                    };
                }
        }
    }
    startStageMusicIfPossible() {
        const context = this.ensureAudioContext();
        if (!context || context.state !== 'running' || !this.currentStageId || this.playingStageId === this.currentStageId) {
            return;
        }
        const { play, loopMs } = this.getStageMusicDispatch(this.currentStageId);
        this.playingStageId = this.currentStageId;
        play();
        this.musicPulseInterval = window.setInterval(play, loopMs);
    }
    // ── Stage music phrases — each method schedules the full phrase via delays.        ──
