            itemDropChance: 0.30,
            techDropRateFactor: 1.3,
            xDataDropChanceWeight: 1.5,
            criticalChance: 0.05,
            criticalHitMultiplier: 1.4,
            blockChance: 0.2,
            size: 2.75,
